direct.command:
node --input-type=module <<'NODE'
import fs from 'node:fs';import assert from 'node:assert/strict';import {sha256,taskContractDigest}from'./scripts/remediation/board.mjs';const t=JSON.parse(fs.readFileSync('docs/remediation/tracker.json','utf8')),k=t.tasks.find(x=>x.id==='W19.02'),b=JSON.parse(fs.readFileSync('docs/remediation/design/W19.02/baseline.json','utf8'));assert.equal(k.state,'in_progress');assert.equal(taskContractDigest(k),k.preflight.contract_digest);assert.equal(sha256(fs.readFileSync(k.preflight.plan.path)),k.preflight.plan.sha256);assert.deepEqual(t.journal.filter(x=>x.task_id===k.id&&x.to==='in_progress').at(-1).plan_snapshot,k.preflight);assert(t.authority.local_authorization.scope_task_ids.includes(k.id));assert.equal(sha256(JSON.stringify(t.journal.slice(0,b.prior_journal_length))),b.prior_journal_sha256);for(const f of b.pins)assert.equal(sha256(fs.readFileSync(f.path)),f.sha256,f.path);for(const f of b.owned)if(!f.existed)assert(!fs.existsSync(f.path));assert(t.packages.find(p=>p.id==='W19').decomposition.task_ids.includes(k.id));assert.equal(t.tasks.filter(x=>['in_progress','verification'].includes(x.state)).length,1);console.log(JSON.stringify({at:new Date().toISOString(),GO:true,task:k.id,journal:t.journal.length,contract:k.preflight.contract_digest,pins:b.pins.length,owned:b.owned.length,prior_journal:b.prior_journal_length,pending_source:true}));
NODE

entry_board.command:
node --max-old-space-size=1536 --input-type=module -e 'import fs from '\''node:fs'\'';import{syncBuiltinESMExports}from'\''node:module'\'';import{resolve}from'\''node:path'\'';import{pathToFileURL}from'\''node:url'\'';
const cache=new Map();let cacheBytes=0;
for(const name of ['\''realpathSync'\'','\''statSync'\'']){const original=fs[name],memo=new Map();fs[name]=function(...args){const key=JSON.stringify(args);if(memo.has(key))return memo.get(key);const result=original.apply(this,args);memo.set(key,result);return result;};}
const read=fs.readFileSync;fs.readFileSync=function(...args){const key=JSON.stringify(args);if(cache.has(key))return cache.get(key);const result=read.apply(this,args),size=typeof result==='\''string'\''?Buffer.byteLength(result):result.length;if(size<=33554432){while(cacheBytes+size>536870912&&cache.size){const[first,item]=cache.entries().next().value;cache.delete(first);cacheBytes-=typeof item==='\''string'\''?Buffer.byteLength(item):item.length;}cache.set(key,result);cacheBytes+=size;}return result;};for(const name of ['\''realpathSync'\'','\''statSync'\'','\''readFileSync'\'']){const original=fs[name],failures=new Map();fs[name]=function(...args){const key=JSON.stringify(args);if(failures.has(key))throw failures.get(key);try{return original.apply(this,args);}catch(error){failures.set(key,error);throw error;}};}syncBuiltinESMExports();
const write=process.stdout.write.bind(process.stdout);let notes=0;process.stdout.write=(value,...args)=>{const lines=String(value).split('\''\n'\''),out=lines.filter(line=>{if(line.startsWith('\''NOTE '\'')){notes++;return false;}return true;}).join('\''\n'\'');return write(out,...args);};

const file=resolve('\''scripts/remediation/board.mjs'\''),url=pathToFileURL(file);
for(const command of ['\''check'\'','\''status'\'']){
  process.argv=[process.execPath,file,command];
  const entry=new URL(url);entry.searchParams.set('\''invocation'\'',command);
  await import(entry.href);
  write('\''\nBOARD '\''+command+'\'' exit_status '\''+process.exitCode+'\''; NOTE count '\''+notes+'\''\n'\'');notes=0;
  if(process.exitCode!==0)break;
}
'
